async function toPaying(decline: boolean) {
  const h = await create();
  await h.open('a'); await h.add('a'); await h.add('a');
  if (decline) await h.declineCards();
  await h.checkout('a');
  await h.deliver((await h.inFlight())[0].id);
  assert.equal((await h.cart('a'))!.status, 'paying');
  return h;
}

test('payment timeout, charge went through', async () => {
  const h = await toPaying(false);
  assert.equal((await h.paymentTimeout('zz')).ok, false);
  assert.ok((await h.paymentTimeout('a')).ok);
  assert.equal((await h.paymentTimeout('a')).ok, false);
  for (const cmd of ['cancel', 'returnCart', 'retry', 'abandon', 'add', 'checkout'] as const) {
    assert.equal((await h[cmd]('a')).ok, false, cmd);
  }
  assert.equal((await h.cart('a'))!.status, 'abandoning');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 2 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
});

test('payment timeout, charge declined', async () => {
  const h = await toPaying(true);
  assert.ok((await h.paymentTimeout('a')).ok);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 2 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

