import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('happy path', async () => {
  const h = await create();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  await h.checkout('a');
  const f = await h.inFlight();
  assert.equal(f.length, 1);
  assert.deepEqual({ ...f[0], id: '' }, { id: '', from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('out of stock and decline', async () => {
  const h = await create();
  for (const c of ['a', 'b']) { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); }
  await h.deliverAll();
  assert.equal((await h.cart('b'))!.status, 'failed');
  const g = await create();
  await g.open('a'); await g.add('a'); await g.declineCards(); await g.checkout('a');
  await g.deliverAll();
  assert.equal((await g.cart('a'))!.status, 'declined');
  assert.deepEqual(await g.stock(), { available: 1, reserved: 1 });
  assert.equal((await g.declineCards()).ok, false);
  assert.equal((await g.cancel('a')).ok, false);
  assert.equal((await g.returnCart('a')).ok, false);
  assert.ok((await g.retry('a')).ok);
  assert.equal((await g.retry('a')).ok, false);
  await g.deliverAll();
  assert.equal((await g.cart('a'))!.status, 'declined');
  assert.ok((await g.abandon('a')).ok);
  assert.equal((await g.abandon('a')).ok, false);
  await g.deliverAll();
  assert.equal((await g.cart('a'))!.status, 'failed');
  assert.deepEqual(await g.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await g.payments(), { charged: 0, declining: true });
});

test('retry succeeds after accepting', async () => {
  const h = await create();
  await h.open('a'); await h.add('a'); await h.declineCards(); await h.checkout('a');
  await h.deliverAll();
  await h.acceptCards();
  assert.ok((await h.retry('a')).ok);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'paid');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  assert.deepEqual(await h.payments(), { charged: 1, declining: false });
});

test('return', async () => {
  const h = await create();
  await h.open('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  await h.checkout('a'); await h.deliverAll();
  assert.ok((await h.returnCart('a')).ok);
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  const f = await h.inFlight();
  assert.deepEqual(f.map((m) => [m.to, m.action, m.data]).sort(), [['inventory', 'Release', { qty: 1 }], ['payments', 'Refund', { amount: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
});

test('cancel while reserving', async () => {
  const h = await create();
  await h.open('a'); await h.add('a'); await h.checkout('a');
  assert.ok((await h.cancel('a')).ok);
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'cancelled', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.equal(await h.cart('zz'), null);
  assert.equal((await h.add('zz')).ok, false);
});

